head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > P > caption]<br/>웹접근성 향상을 위해 컴포넌트의 caption 요소에 추가 정보를 설정합니다.",
    "validation" : [
        "caption 요소에 들어갈 추가 정보를 텍스트로 설정합니다.",
        "값을 설정하지 않으면 '달력' 으로 적용됩니다.",
        "팝업 달력의 가운데 요일/날짜 영역은 table 태그로 렌더링되며 caption 요소는 table 태그의 자식 요소로 추가됩니다.",
        "caption 요소에 설정한 추가 정보는 화면에 표시되지 않습니다.",
        "caption 요소에 'w2blind' CSS 클래스가 적용되어 시각적으로 숨겨지며, 스크린리더 전용으로 동작합니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        caption : con_caption.getValue()
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    await $c.gcm.createBasicCalendar(cList, eList);
}



scwin.btn_getInfo_onclick = function (e) {
    let calendarRender = target1.render;
    let captionElement = calendarRender.querySelector('caption');

    if (!captionElement) {
        wf_body_bottom.getObj("scwin").setReturnValue("[caption 요소] 미발견");
        return;
    }

    // validation: caption 요소에 들어갈 추가 정보를 텍스트로 설정 / 값 미설정 시 '달력' 으로 적용
    let captionText = captionElement.textContent;
    wf_body_bottom.getObj("scwin").setReturnValue("[caption 텍스트] 실제 caption 텍스트='" + captionText + "'" + (captionText === '달력' ? " (기본값 '달력' 적용)" : " (설정값 적용)"));

    // validation: caption 요소는 table 태그의 자식 요소로 추가됨
    let parentTag = captionElement.parentElement ? captionElement.parentElement.tagName.toLowerCase() : '없음';
    wf_body_bottom.getObj("scwin").setReturnValue("[caption 위치(table 자식 여부)] 부모 태그=" + parentTag + " → " + (parentTag === 'table' ? "table 의 자식" : "table 의 자식 아님"));

    // validation: caption 요소에 'w2blind' CSS 클래스가 적용되어 시각적으로 숨겨지며, 스크린리더 전용으로 동작
    let className = captionElement.className;
    let hasW2blind = className.split(/\s+/).indexOf('w2blind') !== -1;
    wf_body_bottom.getObj("scwin").setReturnValue("[w2blind 클래스 적용 여부] " + (hasW2blind ? "적용됨" : "미적용") + " (className='" + className + "')");

    // validation: caption 요소에 설정한 추가 정보는 화면에 표시되지 않음 (visually hidden)
    let cs = getComputedStyle(captionElement);
    let offsetH = captionElement.offsetHeight;
    let offsetW = captionElement.offsetWidth;
    let isVisuallyHidden = (cs.position === 'absolute' && (cs.clip === 'rect(0px, 0px, 0px, 0px)' || cs.clip === 'rect(0 0 0 0)' || cs.clipPath === 'inset(50%)') && offsetW <= 1 && offsetH <= 1);
    wf_body_bottom.getObj("scwin").setReturnValue("[화면 표시 여부] " + (isVisuallyHidden ? "화면 미표시 (스크린리더 전용)" : "화면 표시됨") + " (position=" + cs.position + ", clip=" + cs.clip + ", clipPath=" + cs.clipPath + ", offsetW=" + offsetW + ", offsetH=" + offsetH + ")");
}
